ch=open("Specification/appendices/changes.tex").read()
def norm(s):
    s=re.sub(r'\\pushtabs|\\poptabs|\\=|\\\+|\\-|\{\\tt~+\}','',s)
    s=s.replace('\\\\','')
    s=re.sub(r'\s+',' ',s).strip()
    return s
chn=norm(ch)
for f in files:
    d=subprocess.run(["git","diff","-U0","e5414f5bf","HEAD","--",f],capture_output=True,text=True).stdout
    for line in d.splitlines():
        if line.startswith('-') and not line.startswith('---'):
            t=line[1:]
            if t.strip()=='' or t.lstrip().startswith('%'): continue
            n=norm(t)
            if not n: continue
            if n not in chn:
                print("NOTQUOTED",f,":",t[:140])

